# filename: email_templates.py
# Code Generated by Sidekick is for learning and experimentation purposes only.

from dataclasses import dataclass


@dataclass
class EmailTemplate:
    subject: str
    html:    str
    text:    str


# ── Safe helpers ──────────────────────────────────────────────────────────────

def _safe(value, default=0):
    """Return value if it is not None, otherwise default."""
    return value if value is not None else default


def _amount_str(amount, currency) -> str:
    """Format cents (int) or dollars (float) as '$X.XX CUR'. Never crashes on None."""
    safe_amt = _safe(amount, 0)
    safe_cur = currency if currency else "usd"
    # Treat whole integers >= 100 as cents → convert to dollars
    if isinstance(safe_amt, int) and safe_amt >= 100:
        dollars = safe_amt / 100
    else:
        dollars = float(safe_amt)
    return f"${dollars:.2f} {safe_cur.upper()}"


def _refund_amount_str(ctx: dict) -> str:
    """Pick refund_amount → amount → 0, safely."""
    amt = _safe(ctx.get("refund_amount"), _safe(ctx.get("amount"), 0))
    return _amount_str(amt, ctx.get("currency", "usd"))


# ── Template builder — lazy (if/elif, not dict) ───────────────────────────────

def get_template(event: str, ctx: dict) -> EmailTemplate:
    """
    Build and return only the template that matches `event`.
    No other template body is evaluated, so missing context fields
    for irrelevant events can never cause a crash.
    """
    amt  = _amount_str(_safe(ctx.get("amount"), 0), ctx.get("currency", "usd"))
    pid  = ctx.get("payment_id", "")
    name = ctx.get("customer_name", "Valued Customer")

    # ── payment.authorized ───────────────────────────────────────────────────
    if event == "payment.authorized":
        return EmailTemplate(
            subject=f"Payment Authorized — {amt}",
            html=f"""
            <h2>Hi {name},</h2>
            <p>Your payment of <strong>{amt}</strong> has been authorized.</p>
            <p>Payment reference: <code>{pid}</code></p>
            <p>Your card will be charged once the merchant confirms the order.</p>
            <hr/><p style="color:#888;font-size:12px">Payment Gateway — Every dollar tracked.</p>
            """,
            text=f"Hi {name}, your payment of {amt} has been authorized. Ref: {pid}",
        )

    # ── payment.captured ─────────────────────────────────────────────────────
    if event == "payment.captured":
        return EmailTemplate(
            subject=f"Payment Confirmed — {amt}",
            html=f"""
            <h2>Hi {name},</h2>
            <p>Your payment of <strong>{amt}</strong> has been successfully processed.</p>
            <p>Payment reference: <code>{pid}</code></p>
            <p>Thank you for your purchase!</p>
            <hr/><p style="color:#888;font-size:12px">Payment Gateway</p>
            """,
            text=f"Hi {name}, payment of {amt} confirmed. Ref: {pid}",
        )

    # ── payment.failed ───────────────────────────────────────────────────────
    if event == "payment.failed":
        reason = ctx.get("failure_reason") or "Unknown error"
        return EmailTemplate(
            subject=f"Payment Failed — {amt}",
            html=f"""
            <h2>Hi {name},</h2>
            <p>Unfortunately your payment of <strong>{amt}</strong> could not be processed.</p>
            <p>Reason: <em>{reason}</em></p>
            <p>Payment reference: <code>{pid}</code></p>
            <p>Please try again or use a different payment method.</p>
            <hr/><p style="color:#888;font-size:12px">Payment Gateway</p>
            """,
            text=f"Hi {name}, payment of {amt} failed. Reason: {reason}. Ref: {pid}",
        )

    # ── payment.refunded ─────────────────────────────────────────────────────
    if event == "payment.refunded":
        r_amt = _refund_amount_str(ctx)
        return EmailTemplate(
            subject=f"Refund Processed — {r_amt}",
            html=f"""
            <h2>Hi {name},</h2>
            <p>A refund of <strong>{r_amt}</strong> has been processed
               to your original payment method.</p>
            <p>Original payment reference: <code>{pid}</code></p>
            <p>Please allow 3–5 business days for the funds to appear.</p>
            <hr/><p style="color:#888;font-size:12px">Payment Gateway</p>
            """,
            text=f"Hi {name}, refund of {r_amt} processed for payment {pid}.",
        )

    # ── payment.voided ───────────────────────────────────────────────────────
    if event == "payment.voided":
        return EmailTemplate(
            subject=f"Payment Voided — {amt}",
            html=f"""
            <h2>Hi {name},</h2>
            <p>Your payment authorization of <strong>{amt}</strong> has been voided.</p>
            <p>No funds have been charged. Reference: <code>{pid}</code></p>
            <hr/><p style="color:#888;font-size:12px">Payment Gateway</p>
            """,
            text=f"Hi {name}, payment {pid} voided. No charge made.",
        )

    # ── fraud.detected ───────────────────────────────────────────────────────
    if event == "fraud.detected":
        return EmailTemplate(
            subject="Security Alert — Suspicious Activity Detected",
            html=f"""
            <h2>Hi {name},</h2>
            <p>We detected suspicious activity on a recent payment attempt of
               <strong>{amt}</strong>.</p>
            <p>The transaction has been blocked for your protection.</p>
            <p>Reference: <code>{pid}</code></p>
            <p>If this was you, please contact support. If not, no action is required.</p>
            <hr/><p style="color:#888;font-size:12px">Payment Gateway Security Team</p>
            """,
            text=f"Security alert: suspicious activity on payment {pid}. Transaction blocked.",
        )

    # ── fallback ──────────────────────────────────────────────────────────────
    return EmailTemplate(
        subject=f"Payment Update — {pid}",
        html=f"<p>Update on payment <code>{pid}</code>: {event}</p>",
        text=f"Payment {pid} update: {event}",
    )
